SET status = 'completed', completed_at = now()
WHERE id = {{$json[0]?.mission_task_id || $json.mission_task_id ? ''' + String($json[0]?.mission_task_id || $json.mission_task_id) + ''' : 'NULL'}}
RETURNING id;
